/bin/bash -lc "python build_solution.py && python - <<'PY'
import json
p='output/solution.json'
d=json.load(open(p))
allowed_h={'forehand','backhand'}
allowed_s={'serve','loop','block','push','flick','lob','smash','chop'}
allowed_e={f'{p}_{e}' for p in ('left','right') for e in ('out','net','winner','double_bounce','not_hitting_ball','miss_on_own_side')}
assert d.keys()=={'rallies'} and len(d['rallies'])==89
prev=-1
for i,r in enumerate(d['rallies']):
 assert set(r)=={'serve_time_sec','strokes','ending_time_sec','ending'}
 assert r['serve_time_sec']>prev and r['ending_time_sec']>=r['serve_time_sec'] and r['ending'] in allowed_e
 assert r['strokes'] and r['strokes'][0]['stroke']=='serve' and r['strokes'][0]['time_sec']==r['serve_time_sec']
 for s in r['strokes']:
  assert s['player'] in {'left','right'} and s['hand'] in allowed_h and s['stroke'] in allowed_s
 prev=r['serve_time_sec']
print('validated_rallies',len(d['rallies']))
print('first',d['rallies'][0])
print('last',d['rallies'][-1])
PY"

